(function(root){
  const normalize=s=>String(s||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/&/g,' and ').replace(/[^\p{L}\p{N}]+/gu,' ').trim();
  const compact=s=>normalize(s).replaceAll(' ','');
  function intent(value){const q=String(value||'').trim();if(/["“”]/.test(q))return {query:q,kind:''};const match=q.match(/\s+(video\s+games?|games?|movies?|films?|anime|manga|visual\s+novels?|vns?|books?|albums?|songs?|tracks?|tv(?:\s+shows?)?|series)$/i);if(!match)return {query:q,kind:''};const query=q.slice(0,match.index).trim();if(!query||/^(the|a|an)$/i.test(query))return {query:q,kind:''};const word=match[1].toLowerCase();const kind=/game/.test(word)?'game':/movie|film/.test(word)?'movie':word==='anime'?'anime':word==='manga'?'manga':/visual|^vn/.test(word)?'visual_novel':/book/.test(word)?'book':/album/.test(word)?'album':/song|track/.test(word)?'track':'tv';return {query,kind};}
  function distance(a,b){let row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){const next=[i];for(let j=1;j<=b.length;j++)next[j]=Math.min(next[j-1]+1,row[j]+1,row[j-1]+(a[i-1]!==b[j-1]));row=next;}return row[b.length];}
  function variants(q){const words=normalize(q).split(' ');if(/(?:\band\b|&)/i.test(q)){const alias=q.replace(/\band\b|&/gi,' ').replace(/\s+/g,' ').trim();if(alias&&alias!==q)return [q,alias];}return words.length>=2&&words.length<=4&&words.every(w=>/^\p{L}{2,}$/u.test(w))?[q,words.join('')]:[q];}
  function relevance(m,q){const query=normalize(q),c=compact(q),titles=[m.title,m.original_title,...(m.alternative_titles||[]),...(m.creators||[]).map(a=>m.title+' '+a)].filter(Boolean).map(normalize);const titleScore=Math.max(...titles.map(t=>{const x=compact(t);if(x===c)return 4;if(c.length>=5&&x.length<=120&&Math.abs(c.length-x.length)<=2&&distance(c,x)<=Math.max(1,Math.floor(c.length*.12)))return 3.5;return t.startsWith(query+' ')?3:t.includes(query)?2:query.split(' ').every(w=>t.split(' ').includes(w))?1:0;}));const words=query.split(' ').filter(Boolean),fields=normalize([m.title,m.original_title,...(m.alternative_titles||[]),...(m.creators||[]),...(m.genres||[]),...(m.platforms||[])].join(' '));return Math.max(titleScore,words.length&&words.every(w=>fields.includes(w))?1.25:0);}
  function prominence(m){const scale={tmdb:10000,igdb:1000,mangaupdates:3000,vndb:3000,musicbrainz:20,anilist:10000,jikan:10000,mal:10000}[m.source.provider]||1000;const votes=Math.min(1.2,Math.log1p(Math.max(0,m.rating_count||0))/Math.log1p(scale));const trend=Math.min(.2,Math.log1p(Math.max(0,m.popularity||0))/50);const age=Math.max(0,new Date().getFullYear()-Number(m.release_date?.slice(0,4)||0));return Math.max(votes,m.search_priority||0)+(Number(m.rating_count)>=1000?.9:0)+trend+((votes||m.search_priority)?0.03/(1+age):0);}
  function creatorAffinity(m,q){const query=normalize(q);if(!query||/["“”]/.test(q))return 0;if(m.discovery_context&&normalize(m.discovery_context.query)===query)return 4.5;const credited=(m.credits||[]).some(c=>/artist|developer|studio|author|writer|director|composer/i.test(c.role||'')&&normalize(c.name)===query);return credited||(m.creators||[]).some(c=>normalize(c)===query)?4.5:0;}
  function rank(records,q){const parsed=intent(q);return records.map((m,i)=>{const relevanceValue=Math.max(relevance(m,parsed.query),creatorAffinity(m,parsed.query)),prominenceValue=prominence(m);return {m,i,kind:parsed.kind?Number(m.kind===parsed.kind):0,score:relevanceValue+(relevanceValue>=2?prominenceValue*1.3:0),prominence:prominenceValue};}).sort((a,b)=>b.kind-a.kind||b.score-a.score||b.prominence-a.prominence||a.i-b.i).map(x=>x.m);}

  function score(value){return String(value).replace(/\d+\.\d+/g,n=>Number(n).toFixed(1));}
  function facetOptions(records,field,filters={},matchesKind=(m,k)=>m.kind===k){const other=field==='genres'?'platforms':'genres',selected=field==='genres'?filters.platform:filters.genre;const eligible=records.filter(m=>(!filters.kind||matchesKind(m,filters.kind))&&(!filters.year||m.release_date?.startsWith(filters.year))&&(!filters.owned||(filters.owned==='owned')===!!m.inLibrary)&&(!selected||(m[other]||[]).includes(selected)));const counts=new Map();for(const m of eligible)for(const value of new Set(m[field]||[]))counts.set(value,(counts.get(value)||0)+1);return [...new Set(records.flatMap(m=>m[field]||[]))].sort().map(value=>({value,count:counts.get(value)||0}));}
  const api={normalize,rank,variants,score,intent,facetOptions,creatorAffinity};if(typeof module==='object')module.exports=api;else root.FolioSearch=api;
})(typeof window==='object'?window:globalThis);
